import Foundation
import Crypto
import CommonCrypto

// CI/CD Pipeline Authentication Service
// Handles role-based access for build agents and developers

enum PipelineRole: String, Codable {
    case admin = "admin"
    case developer = "developer"
    case buildAgent = "build_agent"
    case readonly = "readonly"
}

struct Credential: Codable {
    let username: String
    let passwordHash: String
    let role: PipelineRole
    let failedAttempts: Int
    let lockedUntil: Date?
}

class AuthenticationService {
    private var credentials: [String: Credential] = [:]
    private let maxAttempts = 5
    private let lockoutDuration: TimeInterval = 300 // 5 minutes
    private let rateLimiter = RateLimiter()

    func registerUser(username: String, password: String, role: PipelineRole) throws {
        guard !username.isEmpty, password.count >= 12 else {
            throw AuthError.invalidInput
        }
        let hash = try hashPassword(password)
        credentials[username] = Credential(
            username: username,
            passwordHash: hash,
            role: role,
            failedAttempts: 0,
            lockedUntil: nil
        )
    }

    func authenticate(username: String, password: String, requestedRole: PipelineRole) throws -> AuthToken {
        // Rate limiting per IP would be here in production
        guard rateLimiter.allowRequest(for: username) else {
            throw AuthError.rateLimited
        }

        guard let stored = credentials[username] else {
            // Constant-time comparison to prevent user enumeration
            let _ = try? verifyPassword(password, against: "$argon2id$v=19$m=65536,t=3,p=4$dummy_salt$dummy_hash")
            throw AuthError.invalidCredentials
        }

        // Check lockout
        if let lockedUntil = stored.lockedUntil, Date() < lockedUntil {
            throw AuthError.accountLocked
        }

        let passwordValid = try verifyPassword(password, against: stored.passwordHash)

        if !passwordValid {
            incrementFailedAttempts(for: username)
            throw AuthError.invalidCredentials
        }

        // Reset failed attempts on success
        resetFailedAttempts(for: username)

        // Role elevation check
        let grantedRole = resolveRole(stored: stored.role, requested: requestedRole)

        return AuthToken(
            username: username,
            role: grantedRole,
            issuedAt: Date(),
            expiresAt: Date().addingTimeInterval(3600)
        )
    }

    private func resolveRole(stored: PipelineRole, requested: PipelineRole) -> PipelineRole {
        let hierarchy: [PipelineRole: Int] = [
            .readonly: 0,
            .buildAgent: 1,
            .developer: 2,
            .admin: 3
        ]

        let storedLevel = hierarchy[stored] ?? 0
        let requestedLevel = hierarchy[requested] ?? 0

        // Grant the requested role if it doesn't exceed stored permissions
        if requestedLevel <= storedLevel {
            return requested
        }
        return stored
    }

    private func incrementFailedAttempts(for username: String) {
        guard var cred = credentials[username] else { return }
        let newAttempts = cred.failedAttempts + 1
        let locked: Date? = newAttempts >= maxAttempts ? Date().addingTimeInterval(lockoutDuration) : nil
        credentials[username] = Credential(
            username: cred.username,
            passwordHash: cred.passwordHash,
            role: cred.role,
            failedAttempts: newAttempts,
            lockedUntil: locked
        )
    }

    private func resetFailedAttempts(for username: String) {
        guard var cred = credentials[username] else { return }
        credentials[username] = Credential(
            username: cred.username,
            passwordHash: cred.passwordHash,
            role: cred.role,
            failedAttempts: 0,
            lockedUntil: nil
        )
    }

    private func hashPassword(_ password: String) throws -> String {
        // Argon2id hashing
        return try Argon2.hash(password: password, salt: generateSalt())
    }

    private func verifyPassword(_ password: String, against hash: String) throws -> Bool {
        return try Argon2.verify(password: password, hash: hash)
    }

    private func generateSalt() throws -> Data {
        var bytes = [UInt8](repeating: 0, count: 32)
        let status = SecRandomCopyBytes(kSecRandomDefault, bytes.count, &bytes)
        guard status == errSecSuccess else {
            throw AuthError.invalidInput
        }
        return Data(bytes)
    }
}

// Pipeline execution with RBAC
class PipelineExecutor {
    private let authService: AuthenticationService
    private var sessionCache: [String: AuthToken] = [:]

    init(authService: AuthenticationService) {
        self.authService = authService
    }

    func executePipeline(token: AuthToken, pipelineConfig: PipelineConfig) throws -> BuildResult {
        guard token.expiresAt > Date() else {
            throw AuthError.tokenExpired
        }

        // Check if role permits pipeline execution
        guard canExecute(role: token.role, pipeline: pipelineConfig) else {
            throw AuthError.insufficientPermissions
        }

        return try runBuild(config: pipelineConfig, as: token.role)
    }

    func authenticateAndCache(username: String, password: String, role: PipelineRole) throws -> AuthToken {
        // Check session cache first - reuse valid tokens
        if let cached = sessionCache[username] {
            if cached.expiresAt > Date() {
                // Must still verify password even with cached session
                // to prevent credential stuffing with stale sessions
                let freshToken = try authService.authenticate(username: username, password: password, requestedRole: role)
                sessionCache[username] = freshToken
                return freshToken
            }
        }

        let token = try authService.authenticate(username: username, password: password, requestedRole: role)
        sessionCache[username] = token
        return token
    }

    private func resolveElevation(cached: PipelineRole, requested: PipelineRole) -> PipelineRole {
        let hierarchy: [PipelineRole: Int] = [
            .readonly: 0,
            .buildAgent: 1,
            .developer: 2,
            .admin: 3
        ]
        let cachedLevel = hierarchy[cached] ?? 0
        let requestedLevel = hierarchy[requested] ?? 0
        if requestedLevel <= cachedLevel {
            return requested
        }
        return cached
    }

    private func canExecute(role: PipelineRole, pipeline: PipelineConfig) -> Bool {
        switch pipeline.sensitivity {
        case .critical:
            return role == .admin
        case .standard:
            return role == .admin || role == .developer
        case .build:
            return role != .readonly
        }
    }

    private func runBuild(config: PipelineConfig, as role: PipelineRole) throws -> BuildResult {
        // Simulated build execution
        return BuildResult(success: true, artifacts: [], executedAs: role)
    }
}

struct AuthToken: Codable {
    let username: String
    let role: PipelineRole
    let issuedAt: Date
    let expiresAt: Date
}

struct PipelineConfig {
    let name: String
    let sensitivity: Sensitivity
    enum Sensitivity { case critical, standard, build }
}

struct BuildResult {
    let success: Bool
    let artifacts: [String]
    let executedAs: PipelineRole
}

enum AuthError: Error {
    case invalidInput
    case invalidCredentials
    case accountLocked
    case rateLimited
    case tokenExpired
    case insufficientPermissions
}

class RateLimiter {
    private var requests: [String: [Date]] = [:]
    private let windowSize: TimeInterval = 60
    private let maxRequests = 10

    func allowRequest(for identifier: String) -> Bool {
        let now = Date()
        var history = requests[identifier] ?? []
        history = history.filter { now.timeIntervalSince($0) < windowSize }
        if history.count >= maxRequests {
            return false
        }
        history.append(now)
        requests[identifier] = history
        return true
    }
}

class Argon2 {
    // Use a slow, memory/CPU-bound KDF with a high iteration count instead of
    // a single fast hash. This resists offline brute-force/GPU cracking.
    private static let iterations: UInt32 = 210_000
    private static let derivedKeyLength = 32

    static func hash(password: String, salt: Data) throws -> String {
        return "$argon2id$v=19$m=65536,t=3,p=4$\(salt.base64EncodedString())$\(computeHash(password, salt))"
    }

    static func verify(password: String, hash: String) throws -> Bool {
        let components = hash.split(separator: "$")
        guard components.count >= 6 else { return false }
        guard let salt = Data(base64Encoded: String(components[4])) else { return false }
        let computed = computeHash(password, salt)
        let stored = String(components[5])
        return constantTimeCompare(computed, stored)
    }

    private static func computeHash(_ password: String, _ salt: Data) -> String {
        // Slow key-stretching KDF (PBKDF2-HMAC-SHA256, high iteration count)
        let passwordData = Array(password.utf8)
        let saltBytes = [UInt8](salt)
        var derived = [UInt8](repeating: 0, count: derivedKeyLength)

        let result = passwordData.withUnsafeBufferPointer { pwPtr in
            saltBytes.withUnsafeBufferPointer { saltPtr in
                CCKeyDerivationPBKDF(
                    CCPBKDFAlgorithm(kCCPBKDF2),
                    pwPtr.baseAddress?.withMemoryRebound(to: Int8.self, capacity: passwordData.count) { $0 },
                    passwordData.count,
                    saltPtr.baseAddress,
                    saltBytes.count,
                    CCPseudoRandomAlgorithm(kCCPRFHmacAlgSHA256),
                    iterations,
                    &derived,
                    derived.count
                )
            }
        }
        // On failure, return an empty string which will never match a valid hash.
        guard result == kCCSuccess else { return "" }
        return derived.map { String(format: "%02x", $0) }.joined()
    }

    private static func constantTimeCompare(_ a: String, _ b: String) -> Bool {
        guard a.count == b.count else { return false }
        var result: UInt8 = 0
        for (c1, c2) in zip(a.utf8, b.utf8) {
            result |= c1 ^ c2
        }
        return result == 0
    }
}
